  if (player.vx < -MAX_SPEED) player.vx = -MAX_SPEED;

  player.x += player.vx;
  for (let b of solidBlocks) {
    if (rectOverlap(player, b)) {
      if (player.vx > 0) { player.x = b.x - player.w; player.vx = 0; }
      else if (player.vx < 0) { player.x = b.x + b.w; player.vx = 0; }
    }
  }

  // Vertical movement & jumping
  player.vy += GRAVITY;
  if (player.vy > 10) player.vy = 10;

  let jumpPressed = keyIsDown(38) || keyIsDown(32); 
  if (jumpPressed && !prevJumpPressed && player.jumpCount > 0) {
    player.vy = JUMP_V;
    player.jumpCount--;
  }
  prevJumpPressed = jumpPressed;

  player.y += player.vy;
  let onGround = false;

  for (let b of solidBlocks) {
    if (rectOverlap(player, b)) {
      if (player.vy > 0) {
        player.y = b.y - player.h;
        player.vy = 0;
        onGround = true;
      } else if (player.vy < 0) {
        player.y = b.y + b.h;
        player.vy = 0;
      }
    }
  }

  if (onGround) {
    player.jumpCount = 2;
  }
}

function checkCollisions() {
  // Coins
  for (let i = coins.length - 1; i >= 0; i--) {
    if (rectOverlap(player, coins[i])) {
      coins.splice(i, 1);
      score += 1;
    }
  }

  // Spikes
  for (let s of spikes) {
    if (rectOverlap(player, s)) {
      lives = 0;
      gameState = 'GAMEOVER';
      return;
    }
  }

  // Goal
  if (rectOverlap(player, goal)) {
    score += 10;
    gameState = 'WIN';
  }
}

function renderEnvironment() {
  // Draw blocks (terrain) - Slate Blue
  fill(69, 75, 102);
  for (let b of solidBlocks) {
    rect(b.x, b.y, b.w, b.h);
  }

  // Draw coins - Yellow
  fill(255, 235, 59);
  for (let c of coins) {
    rect(c.x, c.y, c.w, c.h);
  }

  // Draw goal - Orange
  fill(255, 152, 0);
  rect(goal.x, goal.y, goal.w, goal.h);

  // Draw spikes - Red
  fill(244, 67, 54);
  for (let s of spikes) {
    triangle(s.x, s.y + s.h, s.x + s.w / 2, s.y, s.x + s.w, s.y + s.h);
  }

  // Draw player - Green
  fill(76, 175, 80);
  rect(player.x, player.y, player.w, player.h);
}
